const lessons=[{"sentences":[{"speaker":"A","text":"Good morning and welcome to the language center reception desk.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.115833333333334},{"speaker":"B","text":"Hello I would like to register for an evening language course please.","position":2,"audioStartSeconds":4.315833333333333,"audioEndSeconds":8.778041666666667},{"speaker":"A","text":"We offer several options although our Spanish class is very popular right now.","position":3,"audioStartSeconds":8.978041666666666,"audioEndSeconds":13.824166666666667},{"speaker":"B","text":"That sounds wonderful because I want to improve my Spanish skills for travel.","position":4,"audioStartSeconds":14.024166666666666,"audioEndSeconds":18.780083333333334},{"speaker":"A","text":"Let me check the schedule since the beginner group meets on Monday and Wednesday.","position":5,"audioStartSeconds":18.980083333333333,"audioEndSeconds":23.657916666666665},{"speaker":"B","text":"Does the evening session start at six thirty as advertised in the brochure?","position":6,"audioStartSeconds":23.857916666666668,"audioEndSeconds":28.419791666666665},{"speaker":"A","text":"Actually we changed that time because the teacher arrives late from another campus.","position":7,"audioStartSeconds":28.619791666666668,"audioEndSeconds":33.60691666666666},{"speaker":"B","text":"Oh I see so what time should I arrive for the first lesson?","position":8,"audioStartSeconds":33.806916666666666,"audioEndSeconds":37.56979166666667},{"speaker":"A","text":"Classes now begin at seven so you have plenty of time after work.","position":9,"audioStartSeconds":37.76979166666667,"audioEndSeconds":42.201625},{"speaker":"B","text":"That timing works much better for me because my office closes at five.","position":10,"audioStartSeconds":42.401625,"audioEndSeconds":47.02791666666667},{"speaker":"A","text":"Please remember to bring your passport when you come to complete the payment.","position":11,"audioStartSeconds":47.227916666666665,"audioEndSeconds":51.53241666666667},{"speaker":"B","text":"Should I also bring a notebook or any special textbooks for the lesson?","position":12,"audioStartSeconds":51.732416666666666,"audioEndSeconds":56.113875},{"speaker":"A","text":"You only need a simple notebook because the main textbook is provided free.","position":13,"audioStartSeconds":56.313875,"audioEndSeconds":61.141083333333334},{"speaker":"B","text":"Thank you very much for your helpful assistance today.","position":14,"audioStartSeconds":61.34108333333333,"audioEndSeconds":64.88125}],"questions":[{"prompt":"Selected language course: ______","answer":"Spanish","evidenceSentence":3,"evidence":"Spanish class","explanation":"Lớp học mà người học muốn đăng ký là tiếng Tây Ban Nha."},{"prompt":"Meeting days for beginner group: ______","answer":"Monday and Wednesday","evidenceSentence":5,"evidence":"Monday and Wednesday","explanation":"Nhóm học cơ bản họp vào thứ Hai và thứ Tư."},{"prompt":"Original brochure starting time: ______","answer":"six thirty","evidenceSentence":6,"evidence":"six thirty","explanation":"Thời gian bắt đầu ban đầu trong tờ quảng cáo là sáu rưỡi."},{"prompt":"Corrected starting time: ______","answer":"seven","evidenceSentence":9,"evidence":"seven","explanation":"Thời gian bắt đầu mới được đính chính là bảy giờ."},{"prompt":"Required identification document: ______","answer":"passport","evidenceSentence":11,"evidence":"passport","explanation":"Tài liệu cần mang theo để hoàn tất thanh toán là hộ chiếu."},{"prompt":"Required material for notes: ______","answer":"notebook","evidenceSentence":13,"evidence":"notebook","explanation":"Dụng cụ cần mang theo để ghi chép là sổ tay."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
